import {
  Injectable,
  UnauthorizedException,
  ConflictException,
  ForbiddenException,
  BadRequestException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { UserStatus } from '@prisma/client';
import type { Profile } from 'passport-google-oauth20';
import * as bcrypt from 'bcrypt';
import { extname } from 'path';
import { CloudinaryService } from '../cloudinary/cloudinary.service';
import { PrismaService } from '../prisma/prisma.service';
import { RegisterDto, LoginDto } from './dto/auth.dto';

interface UploadedAvatarFile {
  buffer: Buffer;
  mimetype: string;
  originalname: string;
}

const userSelect = {
  id: true,
  email: true,
  fullName: true,
  role: true,
  isPremium: true,
  premiumExpiresAt: true,
  packageId: true,
  package: {
    select: {
      id: true,
      name: true,
      duration: true,
      durationUnit: true,
      days: true,
      months: true,
    },
  },
  avatarUrl: true,
  xp: true,
  level: true,
  streakDays: true,
  status: true,
} as const;

@Injectable()
export class AuthService {
  constructor(
    private prisma: PrismaService,
    private jwtService: JwtService,
    private cloudinary: CloudinaryService,
  ) {}

  async register(dto: RegisterDto) {
    const existing = await this.prisma.user.findUnique({
      where: { email: dto.email.toLowerCase() },
    });
    if (existing) throw new ConflictException('Email đã được sử dụng');

    const hashed = await bcrypt.hash(dto.password, 10);
    const user = await this.prisma.user.create({
      data: {
        email: dto.email.toLowerCase(),
        fullName: dto.fullName.trim(),
        password: hashed,
      },
      select: userSelect,
    });

    return { user: this.sanitizeUser(user), accessToken: this.signToken(user) };
  }

  async login(dto: LoginDto) {
    const user = await this.prisma.user.findUnique({
      where: { email: dto.email.toLowerCase() },
      select: { ...userSelect, password: true },
    });

    if (!user?.password) {
      throw new UnauthorizedException('Email hoặc mật khẩu không đúng');
    }

    if (user.status === UserStatus.LOCKED) {
      throw new ForbiddenException('Tài khoản đã bị khóa. Vui lòng liên hệ hỗ trợ.');
    }

    const valid = await bcrypt.compare(dto.password, user.password);
    if (!valid) {
      throw new UnauthorizedException('Email hoặc mật khẩu không đúng');
    }

    await this.prisma.user.update({
      where: { id: user.id },
      data: { lastActivity: new Date() },
    });

    const { password: _, ...safeUser } = user;
    return {
      user: this.sanitizeUser(safeUser),
      accessToken: this.signToken(safeUser),
    };
  }

  async loginWithGoogle(profile: Profile) {
    const googleId = profile.id;
    const email = profile.emails?.[0]?.value?.toLowerCase();
    const fullName =
      profile.displayName?.trim() ||
      profile.name?.givenName ||
      email?.split('@')[0] ||
      'Người dùng';
    const avatarUrl = profile.photos?.[0]?.value ?? null;

    if (!email) {
      throw new BadRequestException(
        'Google không cung cấp email. Vui lòng dùng tài khoản Google khác.',
      );
    }

    let user = await this.prisma.user.findUnique({
      where: { googleId },
      select: userSelect,
    });

    if (!user) {
      const existingByEmail = await this.prisma.user.findUnique({
        where: { email },
        select: userSelect,
      });

      if (existingByEmail) {
        if (existingByEmail.status === UserStatus.LOCKED) {
          throw new ForbiddenException(
            'Tài khoản đã bị khóa. Vui lòng liên hệ hỗ trợ.',
          );
        }

        user = await this.prisma.user.update({
          where: { id: existingByEmail.id },
          data: {
            googleId,
            avatarUrl: existingByEmail.avatarUrl ?? avatarUrl,
            lastActivity: new Date(),
          },
          select: userSelect,
        });
      } else {
        user = await this.prisma.user.create({
          data: {
            email,
            fullName,
            googleId,
            avatarUrl,
          },
          select: userSelect,
        });
      }
    } else {
      if (user.status === UserStatus.LOCKED) {
        throw new ForbiddenException(
          'Tài khoản đã bị khóa. Vui lòng liên hệ hỗ trợ.',
        );
      }

      user = await this.prisma.user.update({
        where: { id: user.id },
        data: {
          lastActivity: new Date(),
          avatarUrl: user.avatarUrl ?? avatarUrl,
        },
        select: userSelect,
      });
    }

    return {
      user: this.sanitizeUser(user),
      accessToken: this.signToken(user),
    };
  }

  async getProfile(userId: string) {
    let user = await this.prisma.user.findUnique({
      where: { id: userId },
      select: userSelect,
    });
    if (!user || user.status === UserStatus.LOCKED) {
      throw new UnauthorizedException('Phiên đăng nhập không hợp lệ');
    }
    if (
      user.isPremium &&
      user.premiumExpiresAt &&
      user.premiumExpiresAt <= new Date()
    ) {
      user = await this.prisma.user.update({
        where: { id: userId },
        data: { isPremium: false, packageId: null },
        select: userSelect,
      });
    }
    return this.sanitizeUser(user);
  }

  async updateAvatar(userId: string, file: UploadedAvatarFile) {
    const allowed = new Set(['.jpg', '.jpeg', '.png', '.webp']);
    const allowedMimeTypes = new Set([
      'image/jpeg',
      'image/png',
      'image/webp',
    ]);
    const ext = extname(file.originalname).toLowerCase() || '.jpg';
    if (!allowed.has(ext) || !allowedMimeTypes.has(file.mimetype)) {
      throw new BadRequestException('Chỉ hỗ trợ ảnh JPG, PNG hoặc WEBP');
    }
    if (!file.buffer?.length) {
      throw new BadRequestException('File ảnh không hợp lệ');
    }

    const avatarUrl = await this.cloudinary.uploadAvatar(userId, file.buffer);

    const user = await this.prisma.user.update({
      where: { id: userId },
      data: { avatarUrl },
      select: userSelect,
    });

    return this.sanitizeUser(user);
  }

  private signToken(user: { id: string; email: string; role: string }) {
    return this.jwtService.sign({
      sub: user.id,
      email: user.email,
      role: user.role,
    });
  }

  private sanitizeUser<T extends { status?: UserStatus }>(user: T) {
    const { status: _, ...rest } = user;
    return rest;
  }
}
